DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.save_private_campaign(jsonb,boolean)'::regprocedure) INTO def; def:=replace(def,'IF auth.uid() IS NULL THEN','IF auth.uid() IS NULL OR NOT (EXISTS(SELECT 1 FROM public.game_players WHERE user_id=auth.uid() AND role=''narrator'') OR EXISTS(SELECT 1 FROM public.campaigns WHERE owner_id=auth.uid())) THEN'); EXECUTE def; SELECT pg_get_functiondef('public.salon_combat_action(uuid,integer,text,uuid,uuid,integer,integer,text)'::regprocedure) INTO def; def:=replace(def,'(1+floor(random()*6))::integer','public.salon_d6()'); def:=replace(def,'IF p_action=''control'' THEN','IF p_action=''control'' THEN IF c.active AND EXISTS(SELECT 1 FROM public.game_enemies WHERE id=p_enemy_id AND game_id=p_game_id AND zone<>c.zone) THEN RAISE EXCEPTION ''Ce mob est dans une autre salle du combat.''; END IF;'); EXECUTE def; END $$;